@page { margin: 7mm; '.($paper==='a4'?'size:A4;':'size:80mm '.(120+count($ticket['lines'])*14).'mm;').' }
.pdf-header,.pdf-footer {display:none!important;} .pos-receipt {font-family:DejaVu Sans,Arial,sans-serif;color:#15251c;font-size:11px;line-height:1.5;margin:0 auto;max-width:'.($paper==='a4'?'170mm':'66mm').';} .pos-receipt h1{font-size:20px;margin:0;} .pos-receipt header{text-align:center;border-bottom:1px dashed #777;padding-bottom:12px;} .pos-receipt p{margin:5px 0;overflow-wrap:anywhere;} .pos-receipt table{width:100%;min-width:0;border-collapse:collapse;table-layout:fixed;} .pos-receipt th,.pos-receipt td{padding:7px 2px;border:0;border-bottom:1px solid #ddd;font-size:10px;vertical-align:top;overflow-wrap:anywhere;} .pos-receipt th{background:transparent;color:#15251c;text-align:left;} .pos-receipt .number{text-align:right;} .pos-receipt .total{font-size:17px;font-weight:bold;border-top:1px dashed #777;padding-top:8px;} .pos-receipt .cancelled{border:2px solid #9c2222;padding:8px;color:#9c2222;font-weight:bold;} .receipt-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin:16px;font:14px Arial;} .receipt-actions a,.receipt-actions button{border:1px solid #bbb;padding:12px;color:#17482d;background:#fff;border-radius:6px;text-decoration:none;cursor:pointer;} @media print{.receipt-actions{display:none;}body{margin:0;background:white;}}';?>
<?php if(!$pdf):?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($ticket['ticket_number'])?></title><style>body{background:#f4f6f4;margin:16px;}<?=$receiptCss?></style></head><body><nav class="receipt-actions" aria-label="Actions du reçu"><button type="button" onclick="window.print()">Imprimer</button><a href="<?=e(base_url('butchery/pos/tickets/'.$ticket['id'].'?paper=80'))?>">Ticket 80 mm</a><a href="<?=e(base_url('butchery/pos/tickets/'.$ticket['id'].'?paper=a4'))?>">A4</a><a href="<?=e(base_url('butchery/pos/tickets/'.$ticket['id'].'?paper='.$paper.'&export=pdf'))?>">PDF</a></nav><?php else:?><style><?=$receiptCss?></style><?php endif;?>
<article class="pos-receipt" data-pos-receipt><header><h1>DAGRIL</h1><p><?=e($ticket['site_name'])?></p><p>REÇU DE VENTE</p><p><?=e($ticket['ticket_number'])?></p></header>
<?php if($ticket['status']==='cancelled'):?><p class="cancelled">TICKET ANNULÉ</p><p><?=e($ticket['cancelled_at'])?> · <?=e($ticket['cancellation_reason'])?></p><?php endif;?>
<p><?=e(date('d/m/Y à H:i',strtotime($ticket['sold_at'])))?></p><p>Comptoir : <?=e($ticket['counter_name'])?><br>Vendeur : <?=e($ticket['cashier_name'])?><br>Client : <?=e($ticket['customer_name'])?></p>
<table aria-label="Articles vendus"><thead><tr><th style="width:44%">Article</th><th class="number" style="width:26%">Quantité × prix</th><th class="number" style="width:30%">Montant</th></tr></thead><tbody><?php foreach($ticket['lines'] as$line):?><tr><td><?=e($line['item_name'])?></td><td class="number"><?php if(($line['price_unit']??'kg')==='piece'):?><?=e(number_format((int)$line['quantity_pieces'],0,',',' '))?> pièce(s)<br>× <?=$money($line['unit_price'])?> / pièce<?php else:?><?=e(number_format((float)$line['quantity_kg'],3,',',' '))?> kg<?=isset($line['quantity_pieces'])?' · '.e(number_format((int)$line['quantity_pieces'],0,',',' ')).' pièce(s)':''?><br>× <?=$money($line['unit_price'])?> / kg<?php endif;?></td><td class="number"><?=$money($line['amount'])?></td></tr><?php endforeach;?></tbody></table>
<p class="total">TOTAL : <?=$money($ticket['total'])?> <?=e($ticket['currency'])?></p><p>Paiement : <?=e($methods[$ticket['payment_method']])?><br>Reçu : <?=$money($ticket['received_amount'])?> <?=e($ticket['currency'])?><br>Monnaie rendue : <?=$money($ticket['change_amount'])?> <?=e($ticket['currency'])?></p><p>Tous les montants sont en <?=e($ticket['currency'])?>.</p><p style="text-align:center;border-top:1px dashed #777;padding-top:12px;">Merci de votre visite.</p></article>
